import { useState } from 'react'
import { ParkDetails } from './components/ParkDetails/ParkDetails'
import { ParkList } from './components/ParkList/ParkList'
import { ParkMap } from './components/ParkMap/ParkMap'
import { normalizePark } from './data/normalizePark'
import sample from './data/parks.sample.json'

const parks = sample.map(normalizePark)

export default function App() {
  const [selectedParkId, setSelectedParkId] = useState<string | null>(null)
  const selectedPark = parks.find((park) => park.id === selectedParkId)
  const selectionProps = { parks, selectedParkId, onSelectPark: setSelectedParkId }

  function closeDetails() {
    setSelectedParkId(null)
    document.getElementById(`park-list-button-${selectedParkId}`)?.focus()
  }

  return (
    <main>
      <h1>Find a Park</h1>
      <div className="park-layout">
        <div className="park-sidebar">
          <ParkList {...selectionProps} />
          <ParkDetails park={selectedPark} onClose={closeDetails} />
        </div>
        <ParkMap {...selectionProps} />
      </div>
    </main>
  )
}

// @vitest-environment jsdom
import { cleanup, render, screen, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { afterEach, expect, it } from 'vitest'
import App from './App'
import sample from './data/parks.sample.json'

afterEach(cleanup)

it('renders the three named regions with the full sample and no initial selection', () => {
  render(<App />)
  expect(screen.getByRole('region', { name: `Parks (${sample.length})` })).toBeTruthy()
  const details = screen.getByRole('region', { name: 'Park details' })
  expect(within(details).getByText(/no park selected/i)).toBeTruthy()
  expect(screen.getByRole('region', { name: 'Park map' })).toBeTruthy()
})

it('returns focus from details to the selected park’s list button', async () => {
  const user = userEvent.setup()
  render(<App />)
  const parkButton = within(screen.getByRole('list')).getByRole('button', { name: /^Highland Dog Park\s*Address not provided$/ })
  await user.click(parkButton)
  expect(document.activeElement).toBe(screen.getByRole('heading', { name: 'Highland Dog Park' }))

  await user.tab()
  expect(document.activeElement).toBe(screen.getByRole('button', { name: 'Back to list' }))
  await user.keyboard('{Enter}')
  expect(document.activeElement).toBe(parkButton)
  expect(screen.getByRole('region', { name: 'Park details' }).textContent).toMatch(/no park selected/i)
})


:root {
  font-family: system-ui, sans-serif;
  color: #1c3529;
  background: #f6f8f5;
  line-height: 1.5;
}

* { box-sizing: border-box; }
body { margin: 0; }
main { max-width: 76rem; margin: 0 auto; padding: clamp(1rem, 4vw, 3rem); }
h1 { margin: 0 0 1.25rem; font-size: clamp(2rem, 4vw, 3rem); }
h2 { margin: 0; font-size: 1.25rem; }
p { margin: 0.5rem 0 0; }

.park-layout {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 3fr);
  gap: 1rem;
}

.park-sidebar { display: grid; align-content: start; gap: 1rem; }
.panel { background: white; border: 1px solid #c7d3ca; border-radius: 0.5rem; padding: 1.25rem; }
.map-panel { min-height: 21rem; background: #e5ede6; }
:focus-visible { outline: 3px solid #1853a0; outline-offset: 3px; }

@media (max-width: 44rem) {
  .park-layout { grid-template-columns: minmax(0, 1fr); }
  .map-panel { min-height: 12rem; }
}

.park-details-header {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.5rem 1rem;
}

.park-details button {
  padding: 0.5rem 0.75rem;
  border: 1px solid currentColor;
  border-radius: 0.35rem;
  background: white;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.park-details button:focus-visible {
  outline: 3px solid #1853a0;
  outline-offset: 3px;
}

.park-details dl {
  display: grid;
  gap: 0.75rem;
  margin: 1rem 0 0;
}

.park-details dt { font-weight: 600; }
.park-details dd { margin: 0; }
.park-details ul { margin: 0; padding-left: 1.25rem; }

.park-details-hours {
  padding: 0.6rem 0.85rem;
  border-left: 4px solid #34644c;
  border-radius: 0.35rem;
  background: #e8f2eb;
}

.park-details-hours dt { font-weight: 700; }
.park-details-hours dd { font-size: 1.125rem; }

.park-details-photos {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(9rem, 100%), 1fr));
