.park-details-photos figure { margin: 0; }

.park-details-photos img {
  display: block;
  width: 100%;
  aspect-ratio: 3 / 2;
  border-radius: 0.35rem;
  object-fit: cover;
}

.park-details-photos figcaption {
  margin-top: 0.25rem;
  color: #49534d;
  font-size: 0.875rem;
}

.park-photo-label {
  display: inline-block;
  padding: 0.1rem 0.4rem;
  border-radius: 0.25rem;
  background: #e8f2eb;
  color: #1c3529;
  font-weight: 600;
}

.park-list {
  display: grid;
  gap: 0.5rem;
  margin: 0.75rem 0 0;
  padding: 0;
  list-style: none;
}

.park-list-button {
  width: 100%;
  min-height: 44px;
  padding: 0.5rem 0.75rem;
  border: 1px solid #aab9af;
  border-radius: 0.375rem;
  background: white;
  color: inherit;
  font: inherit;
  text-align: start;
  overflow-wrap: anywhere;
  cursor: pointer;
}

.park-list-button:hover {
  background: #f2f6f3;
}

.park-list-button:focus-visible {
  outline: 3px solid #1853a0;
